// GENERATED by `npm run sync:edge` from src/game — do not edit.
import type { Activity, ActivityType } from '../economy/types.ts';

/** The fields of Strava's "SummaryActivity" the game uses. */
export interface StravaActivity {
  id: number;
  /** Newer, more precise field (TrailRun, GravelRide…). */
  sport_type?: string;
  /** Legacy field, still sent. */
  type?: string;
  /** UTC start, ISO 8601. */
  start_date: string;
  /** Start in the athlete's local time, ISO 8601 with a fake "Z". */
  start_date_local: string;
  /** Seconds actually moving. */
  moving_time?: number;
  /** Seconds from start to finish. */
  elapsed_time?: number;
  /** Metres. */
  distance?: number;
  /** True when the athlete typed the activity in by hand. */
  manual?: boolean;
}

const SPORT_TYPES: Record<string, ActivityType> = {
  Walk: 'walk',
  Hike: 'walk',
  Snowshoe: 'walk',
  Run: 'run',
  TrailRun: 'run',
  VirtualRun: 'run',
  Ride: 'cycling',
  VirtualRide: 'cycling',
  MountainBikeRide: 'cycling',
  GravelRide: 'cycling',
  EBikeRide: 'cycling',
  EMountainBikeRide: 'cycling',
  Handcycle: 'cycling',
  Velomobile: 'cycling',
  Swim: 'swimming',
  WeightTraining: 'strength',
  Crossfit: 'strength',
  HighIntensityIntervalTraining: 'strength',
  Workout: 'strength',
  StairStepper: 'strength',
  Elliptical: 'strength',
  Rowing: 'strength',
  VirtualRow: 'strength',
  RockClimbing: 'strength',
  Yoga: 'yoga',
  Pilates: 'mobility',
  Soccer: 'team_sport',
  Basketball: 'team_sport',
  Volleyball: 'team_sport',
  Handball: 'team_sport',
  Rugby: 'team_sport',
  IceHockey: 'team_sport',
  Tennis: 'team_sport',
  Badminton: 'team_sport',
  Padel: 'team_sport',
  Pickleball: 'team_sport',
  Squash: 'team_sport',
  TableTennis: 'team_sport',
};

export function mapStravaSport(sport: string | undefined): ActivityType | null {
  return (sport !== undefined && SPORT_TYPES[sport]) || null;
}

/** Strava gives no step count: estimate it from the distance (≈ 0.75 m walking, 1.05 m running). */
const METERS_PER_STEP: Partial<Record<ActivityType, number>> = { walk: 0.75, run: 1.05 };

/** Calendar day (YYYY-MM-DD) of the activity for the athlete, as Strava reports it. */
export function stravaLocalDay(activity: StravaActivity): string {
  return activity.start_date_local.slice(0, 10);
}

/**
 * A Strava activity → a game activity, or null when the sport is not one the game counts.
 * Activities typed by hand in Strava are treated like manual entries (50 %).
 */
export function stravaToActivity(activity: StravaActivity): Activity | null {
  const type = mapStravaSport(activity.sport_type) ?? mapStravaSport(activity.type);
  const seconds = activity.moving_time ?? activity.elapsed_time ?? 0;
  const startMs = Date.parse(activity.start_date);
  const durationMin = Math.round(seconds / 60);
  if (!type || durationMin <= 0 || !Number.isFinite(startMs)) return null;

  const result: Activity = {
    id: `strava-${activity.id}`,
    type,
    source: activity.manual ? 'manual' : 'strava',
    startMs,
    durationMin,
  };
  const distance = activity.distance;
  if (typeof distance === 'number' && distance > 0) {
    result.distanceKm = distance / 1000;
    const stride = METERS_PER_STEP[type];
    if (stride) result.steps = Math.round(distance / stride);
  }
  return result;
}

/** Access tokens are refreshed a little before they expire. */
export function tokenNeedsRefresh(expiresAtSec: number, nowMs: number, marginSec = 300): boolean {
  return expiresAtSec - marginSec <= Math.floor(nowMs / 1000);
}

export const STRAVA_AUTHORIZE_URL = 'https://www.strava.com/oauth/authorize';
export const STRAVA_TOKEN_URL = 'https://www.strava.com/oauth/token';
export const STRAVA_DEAUTHORIZE_URL = 'https://www.strava.com/oauth/deauthorize';
export const STRAVA_ACTIVITIES_URL = 'https://www.strava.com/api/v3/athlete/activities';
/** Read-only, including activities the athlete keeps private. */
export const STRAVA_SCOPE = 'activity:read_all';

export function stravaAuthorizeUrl(clientId: string, redirectUri: string, state: string): string {
  const params = new URLSearchParams({
    client_id: clientId,
    redirect_uri: redirectUri,
    response_type: 'code',
    approval_prompt: 'auto',
    scope: STRAVA_SCOPE,
    state,
  });
  return `${STRAVA_AUTHORIZE_URL}?${params.toString()}`;
}

/**
 * Where the browser may be sent back after Strava: the app itself (deep link), a local
 * dev server, or the configured web address. Anything else is refused (no open redirect).
 */
export function isAllowedReturnUrl(url: unknown, webOrigin: string | undefined): url is string {
  if (typeof url !== 'string' || url.length > 300) return false;
  if (/^sportmotion:\/\//.test(url) || /^exp(\+[a-z0-9-]+)?:\/\//.test(url)) return true;
  if (/^http:\/\/localhost(:\d+)?(\/|$)/.test(url)) return true;
  return (
    webOrigin !== undefined &&
    webOrigin.length > 0 &&
    (url === webOrigin || url.startsWith(`${webOrigin.replace(/\/$/, '')}/`))
  );
}
